text:
Skill 3's table looks like f(a) XOR g(b): row differences are constant under XOR, and skill 2 has columns that repeat. I measure this for all skills by discrete majority fits of tables to the network's own predictions, which touch no weights, and I cluster rows and columns.

```python
import sys;sys.path.insert(0,".")
from net import *
W={n:load(n) for n in NAMES}
ops={"xor":(lambda x,y:x^y,lambda c,y:c^y),"add":(lambda x,y:(x+y)%16,lambda c,y:(c-y)%16),"sub":(lambda x,y:(x-y)%16,lambda c,y:(c+y)%16)}
res={}
for s in range(4):
    L,_,_=logits(W,s);T=L.argmax(1).reshape(32,32)
    for name,(op,inv) in ops.items():
        best=(0,None,None)
        for start in range(6):
            g=T[start].copy()
            for it in range(8):
                # f(a) = majority over b of inverse
                f=np.array([np.bincount(inv(T[i],g) if name!="sub" else (T[i]+g)%16,minlength=16).argmax() for i in range(32)])
                if name=="xor": g=np.array([np.bincount(T[:,j]^f,minlength=16).argmax() for j in range(32)])
                elif name=="add": g=np.array([np.bincount((T[:,j]-f)%16,minlength=16).argmax() for j in range(32)])
                else: g=np.array([np.bincount((f-T[:,j])%16,minlength=16).argmax() for j in range(32)])
            acc=np.mean(op(f[:,None],g[None,:])==T)
            if acc>best[0]: best=(acc,f.copy(),g.copy())
        res[(s,name)]=best
        print(s,name,round(best[0],3),"f",best[1].tolist(),"g",best[2].tolist())
import pickle;pickle.dump(res,open("fits.pkl","wb"))
