from net import *
codes=pickle.load(open("codes_current.pkl","rb"))
A,Bb=np.meshgrid(np.arange(32),np.arange(32),indexing="ij")
def L_avg(s,steps):
    out=0
    for st in steps:
        d=np.load(f"history/step_{st:05d}.npz");Wh={n:d[n] for n in NAMES}
        L=logits(Wh,s)[0][:,:16];out=out+L/len(steps)
    return out.reshape(32,32,16)
def scores(L,method):
    if method=="p2":
        p=np.exp(L-L.max(2,keepdims=True));p/=p.sum(2,keepdims=True);return p**2
    if method=="p":
        p=np.exp(L-L.max(2,keepdims=True));p/=p.sum(2,keepdims=True);return p
    if method=="log":
        l=L-L.max(2,keepdims=True);return l-np.log(np.exp(l).sum(2,keepdims=True))
    if method=="cent":
        return L-L.mean((0,1),keepdims=True)
    if method=="dbl":
        return L-L.mean(0,keepdims=True)-L.mean(1,keepdims=True)+L.mean((0,1),keepdims=True)
    if method=="dblp":
        C=L-L.mean(0,keepdims=True)-L.mean(1,keepdims=True)+L.mean((0,1),keepdims=True)
        p=np.exp(C-C.max(2,keepdims=True));p/=p.sum(2,keepdims=True);return p
def recover(S,f,g):
    F=np.zeros((32,16));G=np.zeros((32,16))
    for v in range(16):
        F[:,v]=S[A,Bb,(v+g[Bb])%16].sum(1);G[:,v]=S[A,Bb,(f[A]+v)%16].sum(0)
    return F,G
