for st in [1000,1100,1200,1300,1400]:
    steps=[st-50,st-25,st]
    L=L_avg(0,steps)
    ag=np.mean(L.argmax(2)==(f[A]+g[Bb])%16)
    row=[]
    for m in ["p2","p","log","cent","dbl","dblp"]:
        F,G=recover(scores(L,m),f,g);row.append((m,int((F.argmax(1)==f).sum()+(G.argmax(1)==g).sum())))
